def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = 0.0
    cindy_prev = 0.0
    eric_prev = 0.0
    urgent_opp = 0
    rich_threat = 0
    weak_or_broke = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            if bid > highest_prev:
                highest_prev = bid
            if agent_id == 'Cindy':
                cindy_prev = bid
            if agent_id == 'Eric':
                eric_prev = bid
        if opp.get('budget', 0) <= 5 or opp.get('hp', 0) <= 1:
            weak_or_broke += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 2:
            urgent_opp += 1
        if opp.get('budget', 0) >= 500 and opp.get('hp', 0) >= 5:
            rich_threat += 1

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    need = 0.0
    if hp <= 2:
        need += 40.0
    elif hp <= 4:
        need += 24.0
    else:
        need += 8.0

    need += min(20.0, no_water_days * 10.0)
    need += supply_pressure * 18.0
    need += min(18.0, urgent_opp * 4.0)

    market = 0.0
    if cindy_prev > 0:
        market = max(market, cindy_prev * 0.78)
    if eric_prev > 0:
        market = max(market, eric_prev * 0.72)
    if highest_prev > 0:
        market = max(market, highest_prev * 0.68)

    base = 22.0 + need
    bid = max(base, market + 2.0)

    if rich_threat >= 1 and supply <= 18:
        bid += 8.0
    if weak_or_broke >= 2 and hp >= 5 and supply >= 20:
        bid -= 10.0
    if day >= 8:
        bid += 8.0

    reserve_target = max(0.0, (10 - day) * 8.0)
    cap = budget - reserve_target
    if hp <= 2 or no_water_days >= 2:
        cap = budget
    elif hp <= 4:
        cap = max(cap, budget * 0.65)
    else:
        cap = max(cap, budget * 0.45)

    if supply >= 23 and hp >= 5 and no_water_days == 0:
        bid = min(bid, 28.0)
    if supply <= 16:
        bid += 10.0

    bid = min(bid, cap)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # Base affordability
    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))

    # If we are in critical HP, prioritize survival
    if hp <= 2:
        return max(0.0, min(budget, DAILY_SALARY * 0.9))

    # Use only yesterday's immediate trace bids
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate how many allocations are plausible given supply and our requirement
    # (Use int indices safely; no lists here, but keep consistent.)
    supply_int = int(round(float(supply)))
    capacity = max(1, supply_int // WATER_REQ)

    # Determine pressure from opponents' yesterday bids
    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))

        # If they were bidding aggressively, we must match at a fraction to avoid losing
        if highest_prev >= DAILY_SALARY * 0.85:
            # Match pressure but not fully; assume competition splits water
            bid = DAILY_SALARY * 0.35
            # If our HP is healthy, slightly underbid to save budget
            if hp >= 5:
                bid = DAILY_SALARY * 0.28
            # If our HP is mid, bid closer
            elif hp >= 3:
                bid = DAILY_SALARY * 0.38
            # Use a small bump based on highest_prev to stay competitive
            bid = max(bid, min(budget, highest_prev * 0.62))
            return max(0.0, min(budget, bid))

        # Moderate bids: bid around average but cap by our budget and supply pressure
        # If supply likely tight (<=18), raise a bit.
        tight = 1 if supply_int <= 18 else 0
        bid = max(DAILY_SALARY * 0.45, avg_prev * 0.75 + tight * 10.0)
        return max(0.0, min(budget, bid))

    # No opponent traces available: conservative mid bid
    tight = 1 if supply_int <= 18 else 0
    bid = DAILY_SALARY * 0.5 + tight * 12.0
    return max(0.0, min(budget, bid))

